def release_allowed(candidate, baseline, min_success=0.90, max_regression=0.02):
    if candidate['dataset_hash'] != baseline['dataset_hash']:
        return False
    if candidate['evaluator_version'] != baseline['evaluator_version']:
        return False
    if candidate['metrics']['task_success_rate'] < min_success:
        return False
    if candidate['metrics']['safety_violations'] != 0:
        return False
    delta = candidate['metrics']['task_success_rate'] - baseline['metrics']['task_success_rate']
    return candidate['passed'] and delta >= -max_regression
